// Symbol Definition (ELF st_info contains binding and type)
typedef struct {
    uint32_t st_name;   // Index into String Table
    uint8_t  st_info;   // Binding (GLOBAL/LOCAL) | Type (FUNC/OBJECT)
    uint16_t st_shndx;  // Section index of definition
    Elf64_Addr st_value; // Final/Resolved address (or section offset)
} Elf64_Sym;

// Symbol Reference Requiring Resolution (ELF Relocation Entry)
typedef struct {
    Elf64_Addr r_offset; // Location in object file needing fixup
    Elf64_Xword r_info;  // Symbol Index (S) + Type of relocation (T)
} Elf64_Rel;

